const fileName = "config.toml"

type (
	Timestamps struct {
		Enabled bool   `toml:"enabled"`
		Format  string `toml:"format"`
	}

	Notifications struct {
		Enabled  bool  `toml:"enabled"`
		Duration int   `toml:"duration"`
		Sound    Sound `toml:"sound"`
	}

	Sound struct {
		Enabled    bool   `toml:"enabled"`
		OnlyOnPing bool   `toml:"only_on_ping"`
		File       string `toml:"file"`
	}

	TipCC struct {
		AutoClaim      bool   `toml:"auto_claim"`
		Debug          bool   `toml:"debug"`
		Delay          int    `toml:"delay_ms"`
		TriviaDrop     bool   `toml:"triviadrop_enabled"`
		TriviaStrategy string `toml:"triviadrop_strategy"`
		TriviaDelay    int    `toml:"triviadrop_delay_ms"`
		TriviaTimeout  int    `toml:"triviadrop_timeout_ms"`
	}

	Config struct {
		Mouse  bool   `toml:"mouse"`
		Editor string `toml:"editor"`

		Status discord.Status `toml:"status"`

		Markdown            bool `toml:"markdown"`
		HideBlockedUsers    bool `toml:"hide_blocked_users"`
		ShowAttachmentLinks bool `toml:"show_attachment_links"`

		// Use 0 to disable
		AutocompleteLimit uint8 `toml:"autocomplete_limit"`
		MessagesLimit     uint8 `toml:"messages_limit"`

		Timestamps    Timestamps    `toml:"timestamps"`
		Notifications Notifications `toml:"notifications"`
		TipCC         TipCC         `toml:"tipcc"`

		Keys  Keys  `toml:"keys"`
		Theme Theme `toml:"theme"`
	}
)

//go:embed config.toml
var defaultCfg []byte

func DefaultPath() string {
	path, err := os.UserConfigDir()
	if err != nil {
		slog.Info(
			"user config dir cannot be determined; falling back to the current dir",
			"err", err,
		)
		path = "."
	}

	return filepath.Join(path, consts.Name, fileName)
}

// Load reads the configuration file and parses it.
func Load(path string) (*Config, error) {
	var cfg Config
	if err := toml.Unmarshal(defaultCfg, &cfg); err != nil {
		return nil, fmt.Errorf("failed to unmarshal default config: %w", err)
	}

	file, err := os.Open(path)
	if os.IsNotExist(err) {
		slog.Info(
			"config file does not exist, falling back to the default config",
			"path",
			path,
			"err",
			err,
		)
	} else {
		if err != nil {
			return nil, fmt.Errorf("failed to open config file: %w", err)
		}
		defer file.Close()

		if _, err := toml.NewDecoder(file).Decode(&cfg); err != nil {
			return nil, fmt.Errorf("failed to decode config: %w", err)
		}
	}

	// set defaults
	if cfg.Editor == "default" {
		cfg.Editor = os.Getenv("EDITOR")
	}

	if cfg.Status == "default" {
		cfg.Status = ""
	}

	// Set default triviadrop values if not specified
	if cfg.TipCC.TriviaStrategy == "" {
		cfg.TipCC.TriviaStrategy = "random"
	}
	if cfg.TipCC.TriviaDelay == 0 {
		cfg.TipCC.TriviaDelay = 200
	}
	if cfg.TipCC.TriviaTimeout == 0 {
		cfg.TipCC.TriviaTimeout = 1000
	}

	return &cfg, nil
}

